/** Copy only the named keys that were actually provided. */
function pick<T extends Record<string, unknown>>(source: T, keys: string[]): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const key of keys) {
    const value = (source as Record<string, unknown>)[key];
    if (value !== undefined) out[key] = value;
  }
  return out;
}

/**
 * Gather the per-field file arguments back into uploads.
 *
 * A field the caller left out entirely is skipped, so an optional file stays
 * optional. One given both ways prefers the inline bytes, since those cannot
 * have gone stale on someone else's disk. List-valued fields (voice cloning
 * samples, fine-tune data) produce one upload per entry, all under the same
 * form field name, which is what multipart expects for a repeated file.
 */
function collectFiles<T extends Record<string, unknown>>(
  source: T,
  fields: { field: string; multiple: boolean }[],
): FilePart[] {
  const out: FilePart[] = [];
  const src = source as Record<string, unknown>;
  const strings = (v: unknown): string[] =>
    Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string') : [];
  for (const { field, multiple } of fields) {
    if (multiple) {
      const paths = strings(src[`${field}_paths`]);
      const b64 = strings(src[`${field}_base64_list`]);
      const names = strings(src[`${field}_filenames`]);
      const count = Math.max(paths.length, b64.length);
      for (let i = 0; i < count; i++) {
        out.push({ field, path: paths[i], base64: b64[i], filename: names[i] });
      }
      continue;
    }
    const path = src[`${field}_path`];
    const base64 = src[`${field}_base64`];
    const filename = src[`${field}_filename`];
    if (typeof path !== 'string' && typeof base64 !== 'string') continue;
    out.push({
      field,
      path: typeof path === 'string' ? path : undefined,
      base64: typeof base64 === 'string' ? base64 : undefined,
      filename: typeof filename === 'string' ? filename : undefined,
    });
  }
  return out;
}

/**
 * Query values must be scalars. A composite reaching this point would otherwise
 * be stringified as "[object Object]" and silently filter on nothing.
 */
function pickQuery<T extends Record<string, unknown>>(
  source: T,
  keys: string[],
  csvKeys: string[] = [],
): Query {
  const out: Query = {};
  for (const key of keys) {
    const value = (source as Record<string, unknown>)[key];
    if (value === undefined) continue;
    if (value === null || typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
      out[key] = value;
    } else if (Array.isArray(value)) {
      out[key] = csvKeys.includes(key)
        ? value.map((v) => String(v)).join(',')
        : value.map((v) => String(v));
    } else {
      out[key] = JSON.stringify(value);
    }
  }
  return out;
}

